package com.franco.desco.adapter.in.web.salesoperation;import com.franco.desco.application.salesoperation.*;import com.franco.desco.application.shared.pagination.PageRequest;import com.franco.desco.domain.salesoperation.SalesOperationModels;import org.springframework.stereotype.Component;
@Component public class SalesOperationWebMapper{public SalesOperationCommands.ListOperations list(int p,int t,Long camp,String estado){return new SalesOperationCommands.ListOperations(new PageRequest<>(p,t,new SalesOperationCommands.Filter(camp,estado),null,null));}public SalesOperationResponses.Summary response(SalesOperationModels.Summary x){return new SalesOperationResponses.Summary(x.operativoVentaId(),x.campaniaVentaId(),x.campania(),x.codigo(),x.fechaInicioProgramada(),x.fechaFinProgramada(),x.fechaInicioReal(),x.fechaFinReal(),x.cantidadJabasRecibidas(),x.jabasAsignadas(),x.jabasDevueltas(),x.jabasDisponibles(),x.jabasPendientes(),x.kilosRecibidos(),x.kilosAceptados(),x.kilosRechazados(),x.estadoProceso(),x.observacion(),x.participantes(),x.entregas(),x.incidenciasPendientes());}public SalesOperationResponses.Detail response(SalesOperationModels.Detail x){var h=x.operativo();return new SalesOperationResponses.Detail(new SalesOperationResponses.Header(h.operativoVentaId(),h.codigo(),h.campaniaVentaId(),h.campania(),h.fechaInicioProgramada(),h.fechaFinProgramada(),h.fechaInicioReal(),h.fechaFinReal(),h.estadoProceso(),h.observacion(),h.jabasRecibidas(),h.jabasAsignadas(),h.jabasDevueltas(),h.jabasPendientes(),h.jabasDisponibles()),x.zonas().stream().map(z->new SalesOperationResponses.Zone(z.zonaProductivaId(),z.codigo(),z.nombre())).toList(),x.participantes().stream().map(p->new SalesOperationResponses.Participant(p.operativoSocioId(),p.estadoParticipacion(),p.participacionId(),p.numeroDocumento(),p.socioNombre())).toList(),x.entregas().stream().map(d->new SalesOperationResponses.Delivery(d.entregaSocioId(),d.codigoLote(),d.fechaHora(),d.pesoAceptadoKg(),d.estadoControlCalidad(),d.estadoProceso())).toList(),x.incidencias().stream().map(i->new SalesOperationResponses.Incident(i.incidenciaId(),i.tipoIncidencia(),i.severidad(),i.descripcion(),i.estadoIncidencia())).toList());}}
